-- EXTRACT(DAY_HOUR ...) of a column of a view, of a derived table and of a CTE whose
-- expression drops the day in MySQL (a literal, DATE(), COALESCE), merged or not; of IF and
-- CASE whose branches drop it; of the functions not measured in extract-forms.txt.
DROP VIEW IF EXISTS ev_merge;
DROP VIEW IF EXISTS ev_temptable;
DROP TABLE IF EXISTS et;
CREATE TABLE et (id INT PRIMARY KEY, dt DATETIME NULL, d DATE NULL);
INSERT INTO et VALUES (1, '2024-05-06 07:08:09', '2024-05-06');
CREATE ALGORITHM = MERGE VIEW ev_merge AS SELECT id, DATE(dt) AS x, COALESCE(dt, dt) AS y, TIMESTAMP '2024-05-06 07:08:09' AS z, dt FROM et;
CREATE ALGORITHM = TEMPTABLE VIEW ev_temptable AS SELECT id, DATE(dt) AS x, COALESCE(dt, dt) AS y, TIMESTAMP '2024-05-06 07:08:09' AS z, dt FROM et;
SELECT 'view merge' AS form, EXTRACT(DAY_HOUR FROM x) AS x, EXTRACT(DAY_HOUR FROM y) AS y, EXTRACT(DAY_HOUR FROM z) AS z, EXTRACT(DAY_HOUR FROM dt) AS dt FROM ev_merge;
SELECT 'view temptable' AS form, EXTRACT(DAY_HOUR FROM x) AS x, EXTRACT(DAY_HOUR FROM y) AS y, EXTRACT(DAY_HOUR FROM z) AS z, EXTRACT(DAY_HOUR FROM dt) AS dt FROM ev_temptable;
SELECT 'derived' AS form, EXTRACT(DAY_HOUR FROM x) AS x, EXTRACT(DAY_HOUR FROM y) AS y, EXTRACT(DAY_HOUR FROM z) AS z FROM (SELECT DATE(dt) AS x, COALESCE(dt, dt) AS y, TIMESTAMP '2024-05-06 07:08:09' AS z FROM et) AS q;
SELECT 'derived limit' AS form, EXTRACT(DAY_HOUR FROM x) AS x, EXTRACT(DAY_HOUR FROM y) AS y, EXTRACT(DAY_HOUR FROM z) AS z FROM (SELECT DATE(dt) AS x, COALESCE(dt, dt) AS y, TIMESTAMP '2024-05-06 07:08:09' AS z FROM et LIMIT 1) AS q;
WITH c AS (SELECT DATE(dt) AS x, COALESCE(dt, dt) AS y, TIMESTAMP '2024-05-06 07:08:09' AS z FROM et) SELECT 'cte' AS form, EXTRACT(DAY_HOUR FROM x) AS x, EXTRACT(DAY_HOUR FROM y) AS y, EXTRACT(DAY_HOUR FROM z) AS z FROM c;
SELECT 'union' AS form, EXTRACT(DAY_HOUR FROM x) AS x FROM (SELECT DATE(dt) AS x FROM et UNION ALL SELECT DATE(dt) FROM et) AS q LIMIT 1;
SELECT 'group' AS form, EXTRACT(DAY_HOUR FROM x) AS x FROM (SELECT MAX(dt) AS x FROM et) AS q;
SELECT 'aggregate' AS form, EXTRACT(DAY_HOUR FROM MAX(dt)) AS mx, EXTRACT(DAY_HOUR FROM MIN(d)) AS mn, EXTRACT(DAY_HOUR FROM ANY_VALUE(dt)) AS av FROM et;
SELECT 'window' AS form, EXTRACT(DAY_HOUR FROM FIRST_VALUE(dt) OVER ()) AS fv, EXTRACT(DAY_HOUR FROM LAG(dt, 0) OVER ()) AS lg FROM et;
SELECT 'if literal' AS form, EXTRACT(DAY_HOUR FROM IF(id > 0, TIMESTAMP '2024-05-06 07:08:09', TIMESTAMP '2024-05-06 07:08:09')) AS a, EXTRACT(DAY_HOUR FROM IF(id > 0, DATE(dt), dt)) AS b, EXTRACT(DAY_HOUR FROM IF(id > 0, dt, DATE(dt))) AS c FROM et;
SELECT 'case literal' AS form, EXTRACT(DAY_HOUR FROM CASE WHEN id > 0 THEN TIMESTAMP '2024-05-06 07:08:09' END) AS a, EXTRACT(DAY_HOUR FROM CASE WHEN id > 0 THEN DATE(dt) ELSE dt END) AS b, EXTRACT(DAY_HOUR FROM NULLIF(DATE(dt), d)) AS c FROM et;
SELECT 'functions' AS form, EXTRACT(DAY_HOUR FROM ADDTIME(TIMESTAMP '2024-05-06 07:08:09', '0:00:00')) AS addtime, EXTRACT(DAY_HOUR FROM SUBTIME(dt, '0:00:00')) AS subtime, EXTRACT(DAY_HOUR FROM ADDDATE(dt, 0)) AS adddate, EXTRACT(DAY_HOUR FROM SUBDATE(dt, 0)) AS subdate, EXTRACT(DAY_HOUR FROM DATE_ADD(TIMESTAMP '2024-05-06 07:08:09', INTERVAL 0 DAY)) AS date_add, EXTRACT(DAY_HOUR FROM TIMESTAMPADD(DAY, 0, TIMESTAMP '2024-05-06 07:08:09')) AS tsadd, EXTRACT(DAY_HOUR FROM TIMESTAMP(DATE '2024-05-06', '07:08:09')) AS ts2, EXTRACT(DAY_HOUR FROM STR_TO_DATE('2024-05-06 07', '%Y-%m-%d %H')) AS str FROM et;
SELECT 'now family' AS form, EXTRACT(DAY_HOUR FROM CURRENT_TIMESTAMP) - EXTRACT(HOUR FROM CURRENT_TIMESTAMP) AS cts, EXTRACT(DAY_HOUR FROM LOCALTIMESTAMP) - EXTRACT(HOUR FROM LOCALTIMESTAMP) AS lts, EXTRACT(DAY_HOUR FROM CURDATE()) AS curdate, EXTRACT(DAY_HOUR FROM UTC_DATE()) AS utc_d, EXTRACT(DAY_HOUR FROM DATE('2024-05-06 07:08:09')) AS date_s, EXTRACT(DAY_HOUR FROM TIMESTAMP('2024-05-06 07:08:09')) AS ts_s, EXTRACT(DAY_HOUR FROM LEAST(dt, dt)) AS least_, EXTRACT(DAY_HOUR FROM DATE(dt) - INTERVAL 0 DAY) AS minus FROM et;
SELECT 'emulation' AS form, EXTRACT(DAY FROM DATE(dt)) * 100 + EXTRACT(HOUR FROM DATE(dt)) AS a, EXTRACT(DAY FROM COALESCE(dt, dt)) * 10000 + EXTRACT(HOUR_MINUTE FROM COALESCE(dt, dt)) AS b, EXTRACT(DAY FROM TIMESTAMP '2024-05-06 07:08:09.5') * 1000000000000 + EXTRACT(HOUR_MICROSECOND FROM TIMESTAMP '2024-05-06 07:08:09.5') AS c FROM et;
SELECT 'variable' AS form, @v := TIMESTAMP '2024-05-06 07:08:09' AS v, EXTRACT(DAY_HOUR FROM @v) AS ev FROM et;
DROP VIEW ev_merge;
DROP VIEW ev_temptable;
DROP TABLE et;
